#include <cstddef>
#include <cstdint>
#include <deque>
#include <map>
#include <string>
#include <utility>
#include <vector>

class ReliableEndpoint
{
public:
    explicit ReliableEndpoint(double resendAfter) : resendAfter_{ resendAfter } {}

    bool send(const std::string& message)
    {
        if (message.size() > 1000) return false;
        queue_.push_back({ nextMessage_++, message, 0.0, false });
        return true;
    }

    std::vector<std::uint8_t> update(double now)
    {
        const std::uint16_t sequence{ nextSequence_++ };
        std::vector<std::uint8_t> p;
        put16(p, sequence);
        put16(p, ack_);
        put16(p, ackBits_ >> 16);
        put16(p, ackBits_ & 0xFFFF);
        p.push_back(0);
        std::vector<std::uint32_t> included;
        for (Pending& m : queue_)
        {
            if (m.sent && now - m.lastSent < resendAfter_) continue;
            if (included.size() == 255 || p.size() + 4 + m.text.size() > 1200) break;
            put16(p, m.id & 0xFFFF);
            put16(p, m.text.size());
            p.insert(p.end(), m.text.begin(), m.text.end());
            m.sent = true;
            m.lastSent = now;
            included.push_back(m.id);
        }
        p[8] = static_cast<std::uint8_t>(included.size());
        inFlight_[sequence] = std::move(included);
        return p;
    }

    void receive(const std::vector<std::uint8_t>& p)
    {
        if (p.size() < 9) return;
        std::vector<std::pair<std::uint16_t, std::string>> messages;
        std::size_t at{ 9 };
        for (int i{ 0 }; i < p[8]; ++i)
        {
            if (p.size() - at < 4) return;
            const std::uint16_t id{ be16(p, at) };
            const std::size_t length{ be16(p, at + 2) };
            at += 4;
            if (p.size() - at < length) return;
            const auto first{ p.begin() + static_cast<std::ptrdiff_t>(at) };
            messages.emplace_back(id, std::string(first, first + static_cast<std::ptrdiff_t>(length)));
            at += length;
        }
        if (at != p.size()) return;

        recordReceived(be16(p, 0));

        const std::uint16_t ack{ be16(p, 2) };
        const std::uint32_t bits{ (std::uint32_t{ be16(p, 4) } << 16) | be16(p, 6) };
        acknowledge(ack);
        for (int i{ 0 }; i < 32; ++i)
            if (bits & (1u << i)) acknowledge(static_cast<std::uint16_t>(ack - 1 - i));

        for (auto& [id, text] : messages)
        {
            const int d{ difference(id, nextDeliver_) };
            if (d < 0 || d >= 1024) continue;
            buffer_.emplace(id, std::move(text));
        }
        for (auto it{ buffer_.find(nextDeliver_) }; it != buffer_.end(); it = buffer_.find(nextDeliver_))
        {
            delivered_.push_back(std::move(it->second));
            buffer_.erase(it);
            ++nextDeliver_;
        }
    }

    std::vector<std::string> take()
    {
        std::vector<std::string> out;
        out.swap(delivered_);
        return out;
    }

    std::size_t unacked() const { return queue_.size(); }

private:
    struct Pending
    {
        std::uint32_t id;
        std::string text;
        double lastSent;
        bool sent;
    };

    static void put16(std::vector<std::uint8_t>& b, std::size_t v)
    {
        b.push_back(static_cast<std::uint8_t>(v >> 8));
        b.push_back(static_cast<std::uint8_t>(v));
    }

    static std::uint16_t be16(const std::vector<std::uint8_t>& b, std::size_t i)
    {
        return static_cast<std::uint16_t>((b[i] << 8) | b[i + 1]);
    }

    static int difference(std::uint16_t a, std::uint16_t b)
    {
        return static_cast<std::int16_t>(static_cast<std::uint16_t>(a - b));
    }

    void recordReceived(std::uint16_t s)
    {
        if (!receivedAny_)
        {
            receivedAny_ = true;
            ack_ = s;
            ackBits_ = 0;
            return;
        }
        const int d{ difference(s, ack_) };
        if (d > 0)
        {
            if (d > 32) ackBits_ = 0;
            else
            {
                const std::uint64_t moved{ (std::uint64_t{ ackBits_ } << d) | (std::uint64_t{ 1 } << (d - 1)) };
                ackBits_ = static_cast<std::uint32_t>(moved & 0xFFFFFFFFu);
            }
            ack_ = s;
        }
        else if (d < 0 && -d - 1 < 32)
        {
            ackBits_ |= 1u << (-d - 1);
        }
    }

    void acknowledge(std::uint16_t sequence)
    {
        const auto it{ inFlight_.find(sequence) };
        if (it == inFlight_.end()) return;
        for (const std::uint32_t id : it->second)
            std::erase_if(queue_, [id](const Pending& m) { return m.id == id; });
        inFlight_.erase(it);
    }

    double resendAfter_;
    std::deque<Pending> queue_;
    std::uint32_t nextMessage_{ 0 };
    std::uint16_t nextSequence_{ 0 };
    std::map<std::uint16_t, std::vector<std::uint32_t>> inFlight_;

    bool receivedAny_{ false };
    std::uint16_t ack_{ 0xFFFF };
    std::uint32_t ackBits_{ 0 };

    std::uint16_t nextDeliver_{ 0 };
    std::map<std::uint16_t, std::string> buffer_;
    std::vector<std::string> delivered_;
};

unitTests:
using Bytes = std::vector<std::uint8_t>;
struct Pipe {
    int dropEvery;
    int count{ 0 };
    std::deque<std::pair<int, Bytes>> queue;
    void push(int tick, Bytes p) {
        if (++count % dropEvery == 0) return;
        queue.emplace_back(tick + 2, std::move(p));
    }
    std::vector<Bytes> due(int tick) {
        std::vector<Bytes> out;
        while (!queue.empty() && queue.front().first <= tick) { out.push_back(queue.front().second); queue.pop_front(); }
        return out;
    }
};
TEST("the packet format") {
    ReliableEndpoint a{ 0.1 };
    CHECK(a.send("hi"));
    CHECK(a.update(0) == (Bytes{ 0, 0, 0xFF, 0xFF, 0, 0, 0, 0, 1, 0, 0, 0, 2, 'h', 'i' }));
    CHECK(a.update(0.05) == (Bytes{ 0, 1, 0xFF, 0xFF, 0, 0, 0, 0, 0 }));
    const Bytes r{ a.update(0.1) };
    CHECK_EQ(r.size(), 15u);
    if (r.size() == 15) { CHECK_EQ(r[1], 2); CHECK_EQ(r[14], 'i'); }
    CHECK_EQ(a.unacked(), 1u);
}
TEST("delivery and acknowledgement") {
    ReliableEndpoint a{ 0.1 }, b{ 0.1 };
    a.send("one"); a.send("two"); a.send("three");
    b.receive(a.update(0));
    CHECK(b.take() == (std::vector<std::string>{ "one", "two", "three" }));
    CHECK(b.take().empty());
    const Bytes reply{ b.update(0) };
    CHECK(reply == (Bytes{ 0, 0, 0, 0, 0, 0, 0, 0, 0 }));
    a.receive(reply);
    CHECK_EQ(a.unacked(), 0u);
    CHECK_EQ(a.update(0.5).size(), 9u);
}
TEST("duplicates and reordering") {
    ReliableEndpoint a{ 0.1 }, b{ 0.1 };
    a.send("first");
    const Bytes p0{ a.update(0) };
    a.send("second");
    const Bytes p1{ a.update(0.01) };
    b.receive(p1);
    CHECK(b.take().empty());
    b.receive(p0);
    CHECK(b.take() == (std::vector<std::string>{ "first", "second" }));
    b.receive(p0);
    b.receive(p1);
    CHECK(b.take().empty());
    const Bytes reply{ b.update(0.02) };
    CHECK(reply == (Bytes{ 0, 0, 0, 1, 0, 0, 0, 1, 0 }));
    a.receive(reply);
    CHECK_EQ(a.unacked(), 0u);
}
TEST("malformed packets change nothing") {
    ReliableEndpoint b{ 0.1 };
    b.receive({ 1, 2, 3 });
    b.receive({ 0, 5, 0xFF, 0xFF, 0, 0, 0, 0, 1, 0, 0, 0, 9, 'x' });
    b.receive({ 0, 6, 0xFF, 0xFF, 0, 0, 0, 0, 0, 7 });
    b.receive({ 0, 7, 0xFF, 0xFF, 0, 0, 0, 0, 2, 0, 0, 0, 1, 'x' });
    CHECK(b.take().empty());
    CHECK(b.update(0) == (Bytes{ 0, 0, 0xFF, 0xFF, 0, 0, 0, 0, 0 }));
}
TEST("size limits") {
    ReliableEndpoint a{ 0.1 };
    CHECK(!a.send(std::string(1001, 'x')));
    CHECK(a.send(std::string(1000, 'x')));
    CHECK(a.send(std::string(1000, 'y')));
    CHECK(a.send("z"));
    CHECK_EQ(a.unacked(), 3u);
    const Bytes p1{ a.update(0) };
    CHECK_EQ(p1.size(), 1013u);
    CHECK_EQ(p1[8], 1);
    const Bytes p2{ a.update(0.01) };
    CHECK_EQ(p2.size(), 1018u);
    CHECK_EQ(p2[8], 2);
    ReliableEndpoint many{ 0.1 };
    for (int i{ 0 }; i < 300; ++i) many.send("");
    const Bytes full{ many.update(0) };
    CHECK_EQ(full[8], 255);
    CHECK_EQ(full.size(), 9u + 255u * 4u);
    CHECK_EQ(many.update(0)[8], 45);
}
TEST("a lossy link in both directions") {
    ReliableEndpoint a{ 0.1 }, b{ 0.1 };
    Pipe ab{ 3 }, ba{ 4 };
    std::vector<std::string> sentA, sentB, gotA, gotB;
    bool small{ true };
    for (int tick{ 0 }; tick < 400; ++tick) {
        const double now{ tick * 0.01 };
        if (tick < 50) {
            for (int k{ 0 }; k < 4; ++k) {
                std::string m(static_cast<std::size_t>(1 + (tick * 7 + k * 13) % 40), static_cast<char>('a' + (tick + k) % 26));
                m += std::to_string(sentA.size());
                a.send(m);
                sentA.push_back(m);
            }
        }
        if (tick % 5 == 0 && sentB.size() < 50) {
            const std::string m{ "from b " + std::to_string(sentB.size()) };
            b.send(m);
            sentB.push_back(m);
        }
        const Bytes pa{ a.update(now) }, pb{ b.update(now) };
        small = small && pa.size() <= 1200 && pb.size() <= 1200;
        ab.push(tick, pa);
        ba.push(tick, pb);
        for (const Bytes& p : ab.due(tick)) { b.receive(p); if (tick % 7 == 0) b.receive(p); }
        for (const Bytes& p : ba.due(tick)) a.receive(p);
        for (auto& m : b.take()) gotB.push_back(m);
        for (auto& m : a.take()) gotA.push_back(m);
    }
    CHECK(small);
    CHECK_EQ(gotB.size(), sentA.size());
    CHECK(gotB == sentA);
    CHECK(gotA == sentB);
    CHECK_EQ(a.unacked(), 0u);
    CHECK_EQ(b.unacked(), 0u);
}
TEST("message ids that wrap around") {
    ReliableEndpoint a{ 0.1 }, b{ 0.1 };
    const int total{ 70000 };
    int sent{ 0 }, received{ 0 };
    bool inOrder{ true };
    for (int tick{ 0 }; tick < 3000 && received < total; ++tick) {
        while (sent < total && a.unacked() < 500) a.send(std::to_string(sent++));
        b.receive(a.update(tick * 0.01));
        a.receive(b.update(tick * 0.01));
        for (const auto& m : b.take()) {
            if (m != std::to_string(received)) inOrder = false;
            ++received;
        }
    }
    CHECK_EQ(received, total);
    CHECK(inOrder);
    CHECK_EQ(a.unacked(), 0u);
}

